-- The New 50 collection, shown as "Coming soon", in place of the first six perfumes.
--
-- Run this in the Supabase SQL Editor AFTER the website update that reads
-- these columns is live, so nobody can buy a coming-soon perfume on the old site.
-- Safe to run twice: columns are added only once and no perfume is added twice.

-- "Coming soon": shown in the shop, but it cannot be added to the bag or
-- ordered until it is switched to "On sale" in Admin → Catalogue.
alter table public.products
  add column if not exists coming_soon boolean not null default false,
  add column if not exists audience text;

alter table public.products drop constraint if exists products_audience_check;
alter table public.products
  add constraint products_audience_check check (audience is null or audience in ('Men', 'Women', 'Unisex'));

comment on column public.products.coming_soon is 'Shown in the shop but not for sale yet (the order API refuses it).';
comment on column public.products.audience is 'Who the perfume is for: Men, Women or Unisex. Used by the shop filter and the scent quiz.';

-- Take the first six off the shop. They are hidden, not deleted, so their
-- orders and reviews stay; switch one back on in Admin → Catalogue if needed.
update public.products
set active = false, updated_at = now()
where slug in ('bloom', 'dew-drop', 'lemon-breeze', 'morning-dew', 'night-queen', 'blix');

-- The New 50. Pictures are illustrations kept in the website's
-- public/products/illustrations/ folder; replace them with photos in
-- Admin → Catalogue whenever a bottle is ready.
insert into public.products
  (slug, name, description, price, image_url, gallery_urls, alt, notes, size_volume,
   fragrance_family, scent_profile, occasion, audience, coming_soon, active, display_order)
select v.*
from (values
  ('samrat', 'Samrat', 'Samrat opens with bright mandarin and a warm thread of cinnamon, then settles into smoky oud wrapped in vanilla and creamy sandalwood. Rich and regal, made for the evenings you want to be remembered.', 749, '/products/illustrations/samrat.webp', array['/products/illustrations/samrat.webp'], 'Samrat Eau de Parfum: an illustration of the SAHUMäRIO bottle with oud, cinnamon, vanilla', 'Mandarin · Bergamot · Cinnamon · Oud · Vanilla · Sandalwood', '50 ml', 'Spicy oud', 'Rich, spiced and regal', 'Evenings, weddings and festivals', 'Men', true, true, 10),
  ('rajtilak', 'Rajtilak', 'A golden touch of saffron, like a king''s tilak, laid over smooth leather and dry cedarwood. Bergamot keeps it bright; black musk keeps it close.', 749, '/products/illustrations/rajtilak.webp', array['/products/illustrations/rajtilak.webp'], 'Rajtilak Eau de Parfum: an illustration of the SAHUMäRIO bottle with kesar, leather', 'Bergamot · Mandarin · Saffron (kesar) · Leather · Cedarwood · Black musk', '50 ml', 'Saffron leather', 'Golden saffron on smooth leather', 'Weddings, festivals and special evenings', 'Men', true, true, 20),
  ('shaurya', 'Shaurya', 'Crisp bergamot and lavender meet a dark trail of oud and vetiver. Calm on the surface and strong underneath, a confident scent for every day and late nights.', 749, '/products/illustrations/shaurya.webp', array['/products/illustrations/shaurya.webp'], 'Shaurya Eau de Parfum: an illustration of the SAHUMäRIO bottle with lavender, oud', 'Bergamot · Lemon · Lavender · Oud · Vetiver (khus) · Cedarwood', '50 ml', 'Aromatic woody', 'Lavender over smoky woods', 'Office to evening', 'Men', true, true, 30),
  ('kunwar', 'Kunwar', 'Neroli and mandarin sparkle over soft suede leather and creamy sandalwood. Polished, light and easy to wear, with a quiet richness that lasts into the evening.', 749, '/products/illustrations/kunwar.webp', array['/products/illustrations/kunwar.webp'], 'Kunwar Eau de Parfum: an illustration of the SAHUMäRIO bottle with neroli, leather', 'Mandarin · Bergamot · Neroli · Leather · Sandalwood · White musk', '50 ml', 'Floral leather', 'Fresh orange blossom on soft suede', 'Daytime, office and dates', 'Men', true, true, 40),
  ('maharaja', 'Maharaja', 'Maharaja pours dark rum over smoky oud, with a pinch of black pepper and a warm base of vetiver and sandalwood. Deep, rich and made for grand evenings.', 749, '/products/illustrations/maharaja.webp', array['/products/illustrations/maharaja.webp'], 'Maharaja Eau de Parfum: an illustration of the SAHUMäRIO bottle with rum, oud', 'Mandarin · Orange · Black pepper · Rum · Oud · Vetiver (khus)', '50 ml', 'Boozy oud', 'Dark rum, oud and spice', 'Evenings, parties and celebrations', 'Men', true, true, 50),
  ('ashwa', 'Ashwa', 'Juicy orange and a spark of cinnamon ride over rugged saddle leather, earthy vetiver and cedarwood. Bold and warm, with a touch of vanilla softening the finish.', 749, '/products/illustrations/ashwa.webp', array['/products/illustrations/ashwa.webp'], 'Ashwa Eau de Parfum: an illustration of the SAHUMäRIO bottle with cinnamon, leather, orange', 'Orange · Bergamot · Cinnamon · Leather · Vetiver (khus) · Cedarwood', '50 ml', 'Spicy leather', 'Orange and cinnamon on saddle leather', 'Evenings and weekends', 'Men', true, true, 60),
  ('narangi-elaichi', 'Narangi Elaichi', 'Sun-bright orange and fresh green cardamom over clean, transparent woods. Lively and easy: a fresh everyday scent with a spicy Indian twist.', 749, '/products/illustrations/narangi-elaichi.webp', array['/products/illustrations/narangi-elaichi.webp'], 'Narangi Elaichi Eau de Parfum: an illustration of the SAHUMäRIO bottle with orange, cardamom', 'Orange · Bergamot · Cardamom · Cedarwood · White musk', '50 ml', 'Citrus spicy', 'Bright orange and green cardamom', 'Daytime, office and college', 'Men', true, true, 70),
  ('hara-ananas', 'Hara Ananas', 'Juicy pineapple and zesty lemon lifted by fresh green basil, resting on cool vetiver and cedarwood. Bright, green and full of energy.', 749, '/products/illustrations/hara-ananas.webp', array['/products/illustrations/hara-ananas.webp'], 'Hara Ananas Eau de Parfum: an illustration of the SAHUMäRIO bottle with pineapple, basil', 'Pineapple · Lemon · Bergamot · Basil · Vetiver (khus) · Cedarwood', '50 ml', 'Fruity aromatic', 'Juicy pineapple with fresh green basil', 'Daytime, summer and travel', 'Men', true, true, 80),
  ('nayak', 'Nayak', 'A clean, classic gentleman''s scent: mandarin and lavender with a touch of rosemary, over smooth cedarwood and vetiver. Fresh, neat and always right.', 749, '/products/illustrations/nayak.webp', array['/products/illustrations/nayak.webp'], 'Nayak Eau de Parfum: an illustration of the SAHUMäRIO bottle with lavender, mandarin', 'Mandarin · Bergamot · Rosemary · Lavender · Cedarwood · Vetiver (khus)', '50 ml', 'Aromatic fougère', 'Clean lavender, herbs and woods', 'Office, daytime and every day', 'Men', true, true, 90),
  ('sheetal', 'Sheetal', 'As cooling as its name: crisp lemon and bergamot, fresh basil and neroli over light cedarwood and vetiver. Made for hot afternoons.', 749, '/products/illustrations/sheetal.webp', array['/products/illustrations/sheetal.webp'], 'Sheetal Eau de Parfum: an illustration of the SAHUMäRIO bottle with basil, neroli, lemon', 'Lemon · Bergamot · Basil · Neroli · Cedarwood · Vetiver (khus)', '50 ml', 'Citrus aromatic', 'Cool lemon, basil and neroli', 'Summer days, office and gym', 'Men', true, true, 100),
  ('kali-elaichi', 'Kali Elaichi', 'Cardamom and cracked black pepper over bergamot and grapefruit, deepened with black musk and cedarwood. Spicy, dark and magnetic.', 749, '/products/illustrations/kali-elaichi.webp', array['/products/illustrations/kali-elaichi.webp'], 'Kali Elaichi Eau de Parfum: an illustration of the SAHUMäRIO bottle with cardamom, black pepper', 'Bergamot · Grapefruit · Cardamom · Black pepper · Black musk · Cedarwood', '50 ml', 'Spicy woody', 'Cardamom and black pepper on dark musk', 'Evenings and cooler days', 'Men', true, true, 110),
  ('kesariya-rum', 'Kesariya Rum', 'Mandarin and saffron melt into a glass of dark rum, finished with vanilla, vetiver and sandalwood. Warm, festive and smooth.', 749, '/products/illustrations/kesariya-rum.webp', array['/products/illustrations/kesariya-rum.webp'], 'Kesariya Rum Eau de Parfum: an illustration of the SAHUMäRIO bottle with kesar, rum, mandarin', 'Mandarin · Bergamot · Saffron (kesar) · Rum · Vanilla · Vetiver (khus)', '50 ml', 'Spicy gourmand', 'Saffron, rum and warm vanilla', 'Evenings, festivals and winter', 'Men', true, true, 120),
  ('raat-mogra', 'Raat Mogra', 'Night-blooming jasmine sharpened with black pepper, over dry cedarwood and dark musk. A bold floral for men who like to stand out after dark.', 749, '/products/illustrations/raat-mogra.webp', array['/products/illustrations/raat-mogra.webp'], 'Raat Mogra Eau de Parfum: an illustration of the SAHUMäRIO bottle with jasmine, black pepper', 'Bergamot · Mandarin · Black pepper · Jasmine · Cedarwood · Black musk', '50 ml', 'Floral spicy', 'Night jasmine with black pepper', 'Evenings and nights out', 'Men', true, true, 130),
  ('nirmal', 'Nirmal', 'Pure and simple: sparkling bergamot, lemon and grapefruit with green rosemary over a soft cloud of clean musk. Like a fresh shirt on a bright morning.', 749, '/products/illustrations/nirmal.webp', array['/products/illustrations/nirmal.webp'], 'Nirmal Eau de Parfum: an illustration of the SAHUMäRIO bottle with rosemary, bergamot', 'Bergamot · Lemon · Grapefruit · Rosemary · White musk · Cedarwood', '50 ml', 'Fresh aromatic', 'Pure, clean bergamot and rosemary', 'Every day, office and gym', 'Men', true, true, 140),
  ('shyam-gulab', 'Shyam Gulab', 'A dark rose for men: velvety rose and leather over smoky vetiver, cedarwood and black musk. Romantic, but strong.', 749, '/products/illustrations/shyam-gulab.webp', array['/products/illustrations/shyam-gulab.webp'], 'Shyam Gulab Eau de Parfum: an illustration of the SAHUMäRIO bottle with rose, leather', 'Bergamot · Mandarin · Rose · Leather · Black musk · Vetiver (khus)', '50 ml', 'Rose leather', 'Dark rose on leather and vetiver', 'Evenings and special occasions', 'Men', true, true, 150),
  ('chandan-mirch', 'Chandan Mirch', 'Creamy sandalwood warmed by a crack of black pepper and lifted by mandarin. Smooth, elegant and quietly confident.', 749, '/products/illustrations/chandan-mirch.webp', array['/products/illustrations/chandan-mirch.webp'], 'Chandan Mirch Eau de Parfum: an illustration of the SAHUMäRIO bottle with sandalwood, black pepper', 'Mandarin · Bergamot · Black pepper · Sandalwood · White musk', '50 ml', 'Woody spicy', 'Creamy sandalwood with black pepper', 'Every day and evenings', 'Men', true, true, 160),
  ('dalchini-khus', 'Dalchini Khus', 'Earthy khus (vetiver) warmed with cinnamon and cardamom, softened with sandalwood and a touch of vanilla. Grounded, warm and comforting.', 749, '/products/illustrations/dalchini-khus.webp', array['/products/illustrations/dalchini-khus.webp'], 'Dalchini Khus Eau de Parfum: an illustration of the SAHUMäRIO bottle with cinnamon, vetiver', 'Mandarin · Grapefruit · Cinnamon · Cardamom · Vetiver (khus) · Sandalwood', '50 ml', 'Spicy woody', 'Cinnamon and cardamom on earthy khus', 'Evenings, monsoon and winter', 'Men', true, true, 170),
  ('rasmalai', 'Rasmalai', 'Inspired by the dessert: creamy vanilla and soft musk with cardamom and a few threads of saffron, on smooth sandalwood. Sweet, soft and irresistible.', 749, '/products/illustrations/rasmalai.webp', array['/products/illustrations/rasmalai.webp'], 'Rasmalai Eau de Parfum: an illustration of the SAHUMäRIO bottle with vanilla, cardamom, kesar', 'Mandarin · Cardamom · Saffron (kesar) · Vanilla · Sandalwood · White musk', '50 ml', 'Gourmand', 'Creamy vanilla, cardamom and saffron', 'Evenings, festivals and winter', 'Women', true, true, 180),
