  ('rasbhari', 'Rasbhari', 'Sweet-tart raspberry and mandarin over vanilla cream, soft musk and sandalwood. Playful, creamy and a little addictive.', 749, '/products/illustrations/rasbhari.webp', array['/products/illustrations/rasbhari.webp'], 'Rasbhari Eau de Parfum: an illustration of the SAHUMäRIO bottle with raspberry, vanilla', 'Raspberry · Mandarin · Vanilla · Sandalwood · White musk', '50 ml', 'Fruity gourmand', 'Raspberry and vanilla cream', 'Every day, dates and parties', 'Women', true, true, 260),
