  ('gulab-khus', 'Gulab Khus', 'Rose and khus, the pairing of classic Indian attars, in a modern spray: fresh rose over earthy vetiver, sandalwood and black musk.', 749, '/products/illustrations/gulab-khus.webp', array['/products/illustrations/gulab-khus.webp'], 'Gulab Khus Eau de Parfum: an illustration of the SAHUMäRIO bottle with rose, vetiver', 'Bergamot · Mandarin · Rose · Vetiver (khus) · Sandalwood · Black musk', '50 ml', 'Floral woody', 'Rose and earthy khus, like a classic attar', 'Every day, festivals and evenings', 'Unisex', true, true, 350),
  ('mogra-oud', 'Mogra Oud', 'Heady mogra (jasmine) over rich oud, sandalwood and black musk. Opulent, deep and made for celebrations.', 749, '/products/illustrations/mogra-oud.webp', array['/products/illustrations/mogra-oud.webp'], 'Mogra Oud Eau de Parfum: an illustration of the SAHUMäRIO bottle with jasmine, oud', 'Bergamot · Mandarin · Jasmine · Oud · Sandalwood · Black musk', '50 ml', 'Floral oud', 'White jasmine on rich oud', 'Weddings, festivals and evenings', 'Unisex', true, true, 360),
  ('kesar-kasturi', 'Kesar Kasturi', 'Saffron and dark musk, two treasures of Indian perfumery, with bergamot, sandalwood and a touch of vanilla. Warm, rich and sensual.', 749, '/products/illustrations/kesar-kasturi.webp', array['/products/illustrations/kesar-kasturi.webp'], 'Kesar Kasturi Eau de Parfum: an illustration of the SAHUMäRIO bottle with kesar, black musk', 'Bergamot · Mandarin · Saffron (kesar) · Black musk · Sandalwood · Vanilla', '50 ml', 'Musky spicy', 'Saffron on dark musk', 'Evenings, weddings and winter', 'Unisex', true, true, 370),
  ('ras-oud', 'Ras Oud', 'Juicy raspberry against smoky oud, with black musk, vetiver and sandalwood. A modern oud: dark, fruity and bold.', 749, '/products/illustrations/ras-oud.webp', array['/products/illustrations/ras-oud.webp'], 'Ras Oud Eau de Parfum: an illustration of the SAHUMäRIO bottle with raspberry, oud', 'Raspberry · Bergamot · Oud · Black musk · Vetiver (khus) · Cedarwood', '50 ml', 'Fruity oud', 'Raspberry over smoky oud', 'Evenings and parties', 'Unisex', true, true, 380),
  ('champa-oud', 'Champa Oud', 'Creamy champa (magnolia) on velvety oud, black musk, vanilla and sandalwood. Soft at first, deep underneath.', 749, '/products/illustrations/champa-oud.webp', array['/products/illustrations/champa-oud.webp'], 'Champa Oud Eau de Parfum: an illustration of the SAHUMäRIO bottle with magnolia, oud', 'Mandarin · Bergamot · Magnolia · Oud · Black musk · Vanilla', '50 ml', 'Floral oud', 'Creamy magnolia on velvet oud', 'Evenings, weddings and festivals', 'Unisex', true, true, 390),
  ('hariyali', 'Hariyali', 'Greenery after the rain: fresh basil, bergamot and lemon on soft leather, vetiver and cedarwood. Green, earthy and unusual.', 749, '/products/illustrations/hariyali.webp', array['/products/illustrations/hariyali.webp'], 'Hariyali Eau de Parfum: an illustration of the SAHUMäRIO bottle with basil, leather', 'Bergamot · Lemon · Basil · Leather · Vetiver (khus) · Cedarwood', '50 ml', 'Green leather', 'Fresh basil on green leather', 'Daytime, monsoon and weekends', 'Unisex', true, true, 400),
