  ('chandni', 'Chandni', 'Soft as moonlight: clean white musk with neroli, magnolia and a touch of bergamot. A quiet, skin-close scent for anyone.', 749, '/products/illustrations/chandni.webp', array['/products/illustrations/chandni.webp'], 'Chandni Eau de Parfum: an illustration of the SAHUMäRIO bottle with white musk, neroli, magnolia', 'Bergamot · Mandarin · Neroli · Magnolia · White musk', '50 ml', 'Musky floral', 'Soft white musk, like moonlight on skin', 'Every day, office and nights', 'Unisex', true, true, 420),
  ('chandan-lavender', 'Chandan Lavender', 'Creamy sandalwood with calm lavender and bergamot, softened by white musk and vanilla. Relaxed, smooth and elegant.', 749, '/products/illustrations/chandan-lavender.webp', array['/products/illustrations/chandan-lavender.webp'], 'Chandan Lavender Eau de Parfum: an illustration of the SAHUMäRIO bottle with sandalwood, lavender', 'Bergamot · Mandarin · Lavender · Sandalwood · White musk · Vanilla', '50 ml', 'Woody aromatic', 'Creamy sandalwood and lavender', 'Every day, office and evenings', 'Unisex', true, true, 430),
  ('manek', 'Manek', 'A ruby of a scent (manek in Gujarati): dark cherry over oud, vetiver, black musk and a little vanilla. Deep, glowing and rich.', 749, '/products/illustrations/manek.webp', array['/products/illustrations/manek.webp'], 'Manek Eau de Parfum: an illustration of the SAHUMäRIO bottle with cherry, oud', 'Cherry · Mandarin · Oud · Vetiver (khus) · Black musk · Sandalwood', '50 ml', 'Fruity oud', 'Ruby cherry on dark oud', 'Evenings, parties and winter', 'Unisex', true, true, 440),
  ('garba', 'Garba', 'Made for Navratri nights: rose and a splash of rum over warm sandalwood, black musk and vanilla. Festive, warm and full of life.', 749, '/products/illustrations/garba.webp', array['/products/illustrations/garba.webp'], 'Garba Eau de Parfum: an illustration of the SAHUMäRIO bottle with rose, rum', 'Mandarin · Bergamot · Rose · Rum · Sandalwood · Black musk', '50 ml', 'Floral boozy', 'Rose and rum on warm woods', 'Navratri, festivals and evenings', 'Unisex', true, true, 450),
  ('aadu-elaichi', 'Aadu Elaichi', 'Soft ripe peach with green cardamom, on sandalwood, white musk and cedarwood. Gentle, fresh and a little spicy.', 749, '/products/illustrations/aadu-elaichi.webp', array['/products/illustrations/aadu-elaichi.webp'], 'Aadu Elaichi Eau de Parfum: an illustration of the SAHUMäRIO bottle with peach, cardamom', 'Peach · Mandarin · Cardamom · Sandalwood · White musk · Cedarwood', '50 ml', 'Fruity spicy', 'Soft peach with green cardamom', 'Every day and daytime', 'Unisex', true, true, 460),
  ('kesar-phool', 'Kesar Phool', 'Saffron and neroli blossom on golden sandalwood, white musk and vetiver. Bright, warm and celebratory.', 749, '/products/illustrations/kesar-phool.webp', array['/products/illustrations/kesar-phool.webp'], 'Kesar Phool Eau de Parfum: an illustration of the SAHUMäRIO bottle with kesar, neroli', 'Bergamot · Mandarin · Saffron (kesar) · Neroli · Sandalwood · White musk', '50 ml', 'Floral spicy', 'Saffron and orange blossom', 'Weddings, festivals and every day', 'Unisex', true, true, 470),
  ('seb-kasturi', 'Seb Kasturi', 'Crisp green apple and bergamot over dark black musk and cedarwood. Fresh on top, deep and clean underneath.', 749, '/products/illustrations/seb-kasturi.webp', array['/products/illustrations/seb-kasturi.webp'], 'Seb Kasturi Eau de Parfum: an illustration of the SAHUMäRIO bottle with green apple, black musk', 'Green apple · Bergamot · Black musk · Cedarwood', '50 ml', 'Fruity musky', 'Crisp green apple on dark musk', 'Daytime, college and evenings', 'Unisex', true, true, 480),
  ('elaichi-phool', 'Elaichi Phool', 'Green cardamom and neroli blossom with lemon, on cool khus (vetiver) and cedarwood. Fresh, spicy and calming in the heat.', 749, '/products/illustrations/elaichi-phool.webp', array['/products/illustrations/elaichi-phool.webp'], 'Elaichi Phool Eau de Parfum: an illustration of the SAHUMäRIO bottle with neroli, cardamom, vetiver', 'Lemon · Bergamot · Cardamom · Neroli · Vetiver (khus) · Cedarwood', '50 ml', 'Aromatic floral', 'Cardamom and neroli on cool khus', 'Summer, office and daytime', 'Unisex', true, true, 490),
  ('raat-lavender', 'Raat Lavender', 'Lavender for the night: bergamot and lavender over black musk, cedarwood and a touch of vanilla. Calm, dark and sensual.', 749, '/products/illustrations/raat-lavender.webp', array['/products/illustrations/raat-lavender.webp'], 'Raat Lavender Eau de Parfum: an illustration of the SAHUMäRIO bottle with lavender, black musk', 'Bergamot · Mandarin · Lavender · Black musk · Vanilla · Cedarwood', '50 ml', 'Aromatic musky', 'Lavender at night on black musk', 'Evenings and nights', 'Unisex', true, true, 500)
